--#-package:0BB3C100# -- package signature --
-- Lua file entry IID 0x8bb3c100
-- Based on the NEON ENGINE by RobertaME / Ulisse Wolf --
-- AFTERLIFE NEWS --
-- Puts the fictitious Afterlife statistics (Winners, Sinners, I.M.P. kills, redemptions) in the news ticker.
-- GENERATED by tools/afterlife-news/build_news.py from roster.py: edit roster.py and rebuild, not this file.
--------------------------------------------------------------------------------------------------
-- NEEDS SC4SIM.dll (1.9.3 or later). The DLL registers run_afterlife_balance_variables() and
-- get_news_ticker_character() when a city opens; AFTERLIFE.lua and PACK_CONSTANTS.lua are no longer part of the
-- pack. Without the DLL this script does nothing: every trigger below stays false.
--
-- Once per game month, afterlife_news.update():
--   1. reads this month's values (run_afterlife_balance_variables): the DLL runs the cycle itself at the start of
--      each game month, together with the game's residential simulator, and fills afterlife_grid_var;
--   2. with a chance of NEWS_CHANCE %, picks an event that this month's numbers support;
--   3. asks the DLL for a character on topic for that event (get_news_ticker_character).
-- Each character has one fluff advice below, whose trigger is true only in the month that character is picked; its
-- title is the character's ticker line (LTEXT text@BB3C1000 - text@BB3C1063, CAM_Afterlife_News_en.dat).
--
-- Events and characters (built into SC4SIM.dll):
--   NATURAL_DEATH_REPORT       KATIE_KILLJOY, TOM_TRENCH
--   IMP_KILL_REPORT            BLITZO, MOXXIE, MILLIE, STRIKER
--   REDEMPTION_REPORT          CHARLIE_MORNINGSTAR, VAGGIE, ANGEL_DUST, HUSK, NIFFTY, SIR_PENTIOUS, EGG_BOIS, FAT_NUGGETS, CHERRI_BOMB, BAXTER
--   OVERLORD_REPORT            ALASTOR, VOX, VALENTINO, VELVETTE, CARMILLA_CARMINE, ODETTE_CARMINE, CLARA_CARMINE, ZESTIAL, ROSIE, ZEEZI, PRICK, MIMZY, SUSAN
--   HELL_NATIVE_REPORT         STOLAS, LOONA, VEROSIKA_MAYDAY, OCTAVIA, STELLA, ANDREALPHUS, PAIMON, VASSAGO, FIZZAROLLI, ROBO_FIZZ, CRIMSON, CASH_BUCKZO, BARBIE_WIRE, SALLIE_MAY, VORTEX, GLITZ_AND_GLAM
--   SEVEN_DEADLY_SINS_REPORT   LUCIFER_MORNINGSTAR, LILITH, ASMODEUS, BEELZEBUB, SATAN, MAMMON, LEVIATHAN, BELPHEGOR
--   HEAVEN_REPORT              ADAM, LUTE, ABEL, SERA, EMILY, ST_PETER, SPEAKER_OF_GOD
--   PREMATURE_DEATH_REPORT     NEWS_670_HEALTH_DESK, GATE_INTAKE_CLERK
--------------------------------------------------------------------------------------------------
dofile("adv_fluffnews.lua")

-- afterlife_grid_var starts at zero, so the church and cemetery query UIs (#afterlife_grid_var.FIELD#) show 0 until
-- the first cycle instead of an empty token. The DLL overwrites every field after each cycle.
if (afterlife_grid_var == nil) then
   afterlife_grid_var = {}
end
if (afterlife_grid_var.FALLEN_ANGELS_POPULATION == nil) then afterlife_grid_var.FALLEN_ANGELS_POPULATION = 0 end
if (afterlife_grid_var.HEAVEN_NATIVE_TOTAL == nil) then afterlife_grid_var.HEAVEN_NATIVE_TOTAL = 0 end
if (afterlife_grid_var.HELL_NATIVE_TOTAL == nil) then afterlife_grid_var.HELL_NATIVE_TOTAL = 0 end
if (afterlife_grid_var.IMP_KILLS_THIS_CYCLE == nil) then afterlife_grid_var.IMP_KILLS_THIS_CYCLE = 0 end
if (afterlife_grid_var.NATURAL_DEATHS == nil) then afterlife_grid_var.NATURAL_DEATHS = 0 end
if (afterlife_grid_var.PREMATURE_DEATHS == nil) then afterlife_grid_var.PREMATURE_DEATHS = 0 end
if (afterlife_grid_var.REDEEMED_THIS_CYCLE == nil) then afterlife_grid_var.REDEEMED_THIS_CYCLE = 0 end
if (afterlife_grid_var.REDEEMED_TOTAL == nil) then afterlife_grid_var.REDEEMED_TOTAL = 0 end
if (afterlife_grid_var.SEVEN_DEADLY_SINS_POPULATION == nil) then afterlife_grid_var.SEVEN_DEADLY_SINS_POPULATION = 0 end
if (afterlife_grid_var.SINNER_COUNT_THIS_CYCLE == nil) then afterlife_grid_var.SINNER_COUNT_THIS_CYCLE = 0 end
if (afterlife_grid_var.SINNER_POPULATION_HELL == nil) then afterlife_grid_var.SINNER_POPULATION_HELL = 0 end
if (afterlife_grid_var.TOTAL_DEATHS_THIS_CYCLE == nil) then afterlife_grid_var.TOTAL_DEATHS_THIS_CYCLE = 0 end
if (afterlife_grid_var.WINNER_COUNT_THIS_CYCLE == nil) then afterlife_grid_var.WINNER_COUNT_THIS_CYCLE = 0 end
if (afterlife_grid_var.WINNER_POPULATION_HEAVEN == nil) then afterlife_grid_var.WINNER_POPULATION_HEAVEN = 0 end

afterlife_news = {}
afterlife_news.NEWS_CHANCE    = 50     -- % chance of an Afterlife headline in a month (game.random_chance)
afterlife_news.FREQUENCY_DAYS = 360    -- the same character's line comes back at most once a year
afterlife_news.last_month     = -1     -- game month of the last cycle
afterlife_news.pick           = nil    -- ticker_text_id picked for this month, or nil

-- Events whose condition holds this month, from the values the DLL copied into afterlife_grid_var.
function afterlife_news.candidate_events()
   local v = afterlife_grid_var
   local events = {}
   if (v.IMP_KILLS_THIS_CYCLE > 0)    then table.insert(events, "IMP_KILL_REPORT") end
   if (v.REDEEMED_THIS_CYCLE > 0)     then table.insert(events, "REDEMPTION_REPORT") end
   if (v.WINNER_COUNT_THIS_CYCLE > 0) then table.insert(events, "HEAVEN_REPORT") end
   if (v.NATURAL_DEATHS > 0)          then table.insert(events, "NATURAL_DEATH_REPORT") end
   if (v.PREMATURE_DEATHS > 0)        then table.insert(events, "PREMATURE_DEATH_REPORT") end
   if (v.SINNER_POPULATION_HELL > 0)  then
      table.insert(events, "OVERLORD_REPORT")
      table.insert(events, "SEVEN_DEADLY_SINS_REPORT")
   end
   if (v.HELL_NATIVE_TOTAL > v.FALLEN_ANGELS_POPULATION + v.SEVEN_DEADLY_SINS_POPULATION) then
      table.insert(events, "HELL_NATIVE_REPORT")
   end
   return events
end

function afterlife_news.update()
   if (run_afterlife_balance_variables == nil or get_news_ticker_character == nil) then
      return                                   -- SC4SIM.dll not loaded: no Afterlife news
   end
   local month = game.g_year * 12 + game.g_month
   if (month == afterlife_news.last_month) then
      return                                   -- already done this month
   end
   afterlife_news.last_month = month
   afterlife_news.pick = nil

   run_afterlife_balance_variables("D")
   if (afterlife_grid_var == nil or not game.random_chance(afterlife_news.NEWS_CHANCE)) then
      return
   end
   local events = afterlife_news.candidate_events()
   local count = table.getn(events)
   if (count == 0) then
      return
   end
   -- rotate through the events month by month, so one busy statistic does not take every headline
   local entry = get_news_ticker_character(events[math.mod(month, count) + 1])
   if (entry ~= nil) then
      afterlife_news.pick = entry.ticker_text_id
   end
end

-- Trigger of every Afterlife advice: true when text_id is this month's pick.
function afterlife_news.is_pick(text_id)
   afterlife_news.update()
   return afterlife_news.pick == text_id
end

